50	/** The review's session date range: earliest start to latest end. */
51	export function sessionPeriod(sessions: Session[]): BookFile["period"] {
52	  const times = sessions
53	    .flatMap((s) => [s.started_at, s.ended_at])
54	    .filter((t): t is string => typeof t === "string")
55	    .map((t) => Date.parse(t))
